const response = await fetch("https://gateway.example.test/gateway/v1/media/jobs", {
  method: "POST",
  headers: { authorization: `Bearer ${process.env.AZIZAM_API_KEY}`, 'content-type': 'application/json' },
  body: JSON.stringify({
  "intent": "audio.generate",
  "request": {
    "model": "ace-step-1.5-xl-turbo",
    "tags": "value",
    "lyrics": "value",
    "duration": 1.0,
    "seed": 0,
    "extensions": {
      "com.azizam.workflow": {
        "bpm": 0,
        "timesignature": "2",
        "language": "ar",
        "keyscale": "C major",
        "cfg_scale": 0.0,
        "temperature": 0.0,
        "top_p": 0.0,
        "top_k": 0,
        "min_p": 0.0,
        "steps": 1,
        "cfg": 0.0,
        "sampler": "value",
        "scheduler": "value"
      }
    }
  }
}),
});
if (!response.ok) throw new Error(await response.text());
console.log(await response.json());

