example_request.javascript:
import { writeFile } from 'node:fs/promises';
const response = await fetch("https://gateway.example.test/v1/audio/generate", {
  method: "POST",
  headers: { authorization: `Bearer ${process.env.AZIZAM_API_KEY}`, 'content-type': 'application/json' },
  body: JSON.stringify({
  "model": "sa3-small-sfx",
  "prompt": "A small teal fish mark on a clean white card.",
  "duration": 10,
  "seed": 0
}),
});
if (!response.ok) throw new Error(await response.text());
await writeFile('workflow-output.bin', Buffer.from(await response.arrayBuffer()));

