import { readFile, writeFile } from 'node:fs/promises';
const form = new FormData();
form.append("people", "value");
form.append("thresholds", "value");
form.append("reference", new Blob([await readFile("./reference.png")]), "reference.png");
form.append("candidate", new Blob([await readFile("./candidate.png")]), "candidate.png");
const response = await fetch("https://gateway.example.test/gateway/v1/faces/likeness", {
  method: "POST",
  headers: { authorization: `Bearer ${process.env.AZIZAM_API_KEY}` },
  body: form
});
if (!response.ok) throw new Error(await response.text());
console.log(await response.json());

